import re
from typing import Optional, Tuple, Dict

class Router:
    def __init__(self):
        # List of (pattern_segments, name)
        self.routes = []

    def add(self, pattern: str, name: str) -> None:
        if not pattern.startswith('/'):
            raise ValueError("Pattern must begin with /")

        # Split into segments. 
        # Leading slash results in empty string first element if we use split('/').
        # We want to ignore the leading slash and then split by '/'.
        path_parts = pattern[1:].split('/')
        if not path_parts or (len(path_parts) == 1 and path_parts[0] == ''):
            # This handles "/" case.
            segments = []
        else:
            segments = path_parts

        parsed_segments = []
        for i, seg in enumerate(segments):
            if not seg: # Handle double slashes like //
                continue

            if seg.startswith('{') and seg.endswith('}'):
                inner = seg[1:-1]
                if not inner:
                    raise ValueError("Empty parameter name")

                if inner.endswith(':*'):
                    param_name = inner[:-2]
                    if not param_name:
                        raise ValueError("Empty parameter name")
                    if i != len(segments) - 1:
                        raise ValueError("{name:*} must be the last segment")
                    parsed_segments.append(('wildcard', param_name))
                elif inner == '*': # Should this happen? Contract says {name} or {name:*}.
                    # If it's just {}, it's empty parameter name.
                    pass
                else:
                    param_name = inner
                    parsed_segments.append(('param', param_name))
            elif seg.startswith('{'):
                 raise ValueError("Unmatched brace")
            else:
                parsed_segments.append(('literal', seg))

        # Check for duplicates (same pattern structure)
        for existing_segments, _ in self.routes:
            if existing_segments == parsed_segments:
                raise ValueError(f"Pattern {pattern} already registered.")

        self.routes.append((parsed_segments, name))

    def match(self, path: str) -> Optional[Tuple[str, Dict[str, str]]]:
        # Path always begins with /
        path_parts = path[1:].split('/')
        if not path_parts or (len(path_parts) == 1 and path_parts[0] == ''):
            path_parts = []

        best_match = None # (score, name, params)
        # Score is used to determine specificity.
        # We need a way to compare patterns.

