class TemplateRenderer:
    def __init__(self, template):
        self.template = template
        self.pos = 0

    def render(self, data):
        return self._render_block(data, None)

    def _get_value(self, path, context):
        # Path is a list of keys/fields
        current = context
        for part in path:
