import re

def render(template, data):
    # The requirements are quite specific about the structure and errors.
    # We need to parse the template into a list of "parts". 
    # Each part is either literal text, a comment, an escaped brace, or a placeholder/each block.

    def parse_template(text):
        parts = []
        i = 0
        while i < len(text):
            if text[i:i+3] == r'\{{':
                parts.append({'type': 'literal', 'value': '{{'})
                i += 3
            elif text[i:i+2] == '{{':
                j = i + 2
                while j < len(text) and text[j] != '}':
                    j += 1
                if j >= len(text):
                    raise ValueError("a {{ with no }} after it")
                content = text[i+2:j]
                parts.append({'type': 'tag', 'content': content})
                i = j + 2
            else:
                # Find the next tag start
                next_idx = len(text)
                for k in range(i, len(text)):
                    if text[k:k+3] == r'\{{':
                        next_idx = min(next_idx, k)
                        break
                    if text[k:k+2] == '{{':
                        next_idx = min(next_idx, k)
                        break
                parts.append({'type': 'text', 'value': text[i:next_idx]})
                i = next_idx
        return parts

    def resolve_path(path, context):
        # path is like "a.b.c" or "."
        if not path or path == ".":
            return context

        parts = path.split('.')
        current = context
        for part in parts:
            if part == "": # Should not happen with .field but might if someone writes ..field
                continue
            try:
                # If current is a list and we are looking for an index, 
                # but the prompt says "names that do not begin with . are still looked up in data"
                # and ".field" or "." refers to the item.
                if isinstance(current, dict):
                    current = current[part]
                else:
                    raise KeyError(path)
            except (KeyError, TypeError):
                raise KeyError(path)
        return current

    def evaluate_parts(parts, context, depth=0):
        result = []
        for part in parts:
            if part['type'] == 'text':
                result.append(part['value'])
            elif part['type'] == 'literal':
                result.append(part['value'])
            elif part['type'] == 'tag':
                content = part['content'].strip()
                if content.startswith('!'):
                    # Comment: {{! anything }}
                    continue
                elif content.startswith('#each'):
                    # Each block: {{#each items}} ... {{/each}}
                    if depth > 0:
                        raise ValueError("a {{#each}} inside another {{#each}}")

