        self.template = template
        # Regex to find {{...}} but handle \{{ as escaped
        # We use a negative lookbehind for \ to avoid matching \{{
        # However, the requirement says \{{ renders as literal {{ and starts no placeholder.
        # So we need to identify \{{ first or treat it specially.
        self.tokens = []
