            tokens.append(('TAG', content))
            i = end + 2
        else:
            next_idx = -1
            for j in range(i, len(template)):
                if template[j:j+2] == '{{':
                    next_idx = j
                    break
                if template[j:j+3] == r'\{{':
                    next_idx = j
                    break
            if next_idx == -1:
                tokens.append(('TEXT', template[i:]))
                i = len(template)
            else:
                tokens.append(('TEXT', template[i:next_idx]))
                i = next_idx

