            if t_type == 'TAG':
                if t_val.startswith('#each'):
                    stack.append(idx)
                elif t_val == '/each':
                    if not stack:
                        raise ValueError("Closing repeat with nothing to close")
                    start_idx = stack.pop()
                    parsed_blocks.append((start_idx, idx))

