        output = []
        idx = 0
        while idx < len(token_list):
            t_type, t_val = token_list[idx]
            if t_type == 'TEXT':
                output.append(t_val)
                idx += 1
            elif t_type == 'LITERAL':
                output.append(t_val)
                idx += 1
